using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

[McpServerPromptType]
public sealed class SummarizationPrompts
{
    [McpServerPrompt(Name = "summarize"), Description("Generates a prompt to summarize the given text.")]
    public static GetPromptResult Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Desired summary style: brief, detailed, or bullet-points")] string style = "brief")
    {
        return new GetPromptResult
        {
            Description = "Summarization prompt",
            Messages =
            [
                new PromptMessage
                {
                    Role = Role.User,
                    Content = new TextContentBlock
                    {
                        Text = $"Please provide a {style} summary of the following text:\n\n{text}"
                    }
                }
            ]
        };
    }
}
EOF

